/* Project-specific custom styles go here.
   The Coralred design kit (coralred-ui.css) is already loaded in index.html's <head> —
   don't redeclare cr- classes or kit CSS variables (--hue, --accent, --bg, etc.) here. */

.chapter-reveal {
  opacity: 0;
  transform: translateY(24px);
  transition: opacity 600ms ease-out, transform 600ms ease-out;
}

.chapter-reveal.is-visible {
  opacity: 1;
  transform: translateY(0);
}

.serif-head {
  font-family: 'Noto Serif KR', serif;
  font-weight: 600;
  line-height: 1.25;
  letter-spacing: -0.01em;
  margin: 0;
}

.tint-fill {
  background: #FFF4EF;
}

.nav-link {
  background: none;
  border: 0;
  padding: 0;
  cursor: pointer;
  color: var(--muted);
  transition: color 180ms ease-out;
}

.nav-link:hover {
  color: var(--fg);
}

.bread-row,
.info-row {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  gap: 16px;
  padding: 14px 0;
  border-bottom: 1px solid var(--border);
}

.bread-row:last-child,
.info-row:last-child {
  border-bottom: 0;
}

.hero-caption {
  font-size: 13px;
  color: var(--muted);
}

@media (prefers-reduced-motion: reduce) {
  .chapter-reveal {
    opacity: 1;
    transform: none;
    transition: none;
  }
}

